return new{name,initial,markAt,ids,poles,goals=goals.Select(V).ToArray(),switchAt,phase=w.State.Phase.ToString(),steps=w.CompletedStepCount,time=w.SimulationTime,hp=w.PlayerHealth.CurrentHealth,enemies=w.State.ActiveEnemyCount,budget=w.State.RemainingMarks,failed=w.FailedStepCount,gm=w.GetComponent<GMManager>().Invincible||w.GetComponent<GMManager>().UnlimitedMarks,preMarks,marks,spread,hits,traces,contacts};}
