rks==3&&!w.GetComponent<GMManager>().Invincible&&!w.GetComponent<GMManager>().UnlimitedMarks&&!w.Level.IsIntroductionOpen);w.SubmitMark(2,Polarity.Model.Polarity.Positive);Step(w);Check("far E2 TooFar no spending",w.LastMarkResult.Value.Outcome.ToString()=="TooFar"&&w.State.RemainingMarks==3);w.SubmitMark(5,Polarity.Model.Polarity.Positive);Step(w);w.SubmitMark(5,Polarity.Model.Polarity.Positive);Step(w);Check("same pole unchanged costs only once",w.LastMarkResult.Value.Outcome.ToString()=="Unchanged"&&w.State.RemainingMarks==2);var n=w.CompletedStepCount;w.Level.TogglePause();for(int i=0;i<25;i++)Step(w);Check("pause freezes",w.CompletedStepCount==n&&w.CurrentTimeScale==0);w=await Transfer(false);Check("paused retry clears all runtime state",w.CompletedStepCount==0&&w.PendingMarkCount==0&&w.LastContactPairs.Count==0&&w.State.RemainingMarks==3&&w.PlayerHealth.CurrentHealth==3&&w.CurrentTimeScale==1&&w.Level.CurrentLevelIndex==4);Check("running rejects next",!w.Level.RequestNextLevel());for(int i=0;i<170;i++){Walk(w,i<50?new Vector2(4,-3):new Vector2(-4,-3));Step(w);}w.SubmitMark(6,Polarity.Model.Polarity.Negative);Step(w);Check("actual lower path reaches left and wall blocks mark without cost",Vector2.Distance(w.Player.Rigidbody.position,new Vector2(-4,-3))<.3f&&w.LastMarkResult.Value.Outcome.ToString()=="WallBlocked"&&w.State.RemainingMarks==3,new{p=V(w.Player.Rigidbody.position),outcome=w.LastMarkResult.Value.Outcome.ToString()});w=await Load();for(int i=0;i<330&&w.State.Phase==LevelPhase.Running;i++){Walk(w,i<40?new Vector2(7,0):i<90?new Vector2(7,3):i<280?new Vector2(-4,3):new Vector2(-4,4));Step(w);}w.SubmitMark(6,Polarity.Model.Polarity.Negative);Step(w);Check("upper endpoint reachable and mark restored",w.Player.Rigidbody.position.x<-3.5f&&w.Player.Rigidbody.position.y>3.7f&&w.LastMarkResult.Value.Outcome.ToString()=="Applied",new{p=V(w.Player.Rigidbody.position),outcome=w.LastMarkResult.Value.Outcome.ToString()});w=await Load();while(w.State.Phase==LevelPhase.Running&&w.CompletedStepCount<1000)Step(w);Check("actual Lost modal",w.State.Phase==LevelPhase.Lost&&Object.FindObjectOfType<HUDView>().ModalVisible);w=await Transfer(false);Check("Lost retry fresh",w.State.Phase==LevelPhase.Running&&w.State.ActiveEnemyCount==4&&w.State.RemainingMarks==3&&w.PlayerHealth.CurrentHealth==3);for(int i=0;i<1700&&w.State.Phase==LevelPhase.Running;i++){if(i==0)w.SubmitMark(5,Polarity.Model.Polarity.Positive);if(i==20)w.SubmitMark(3,Polarity.Model.Polarity.Negative);if(i==100)w.SubmitMark(5,Polarity.Model.Polarity.Negative);Walk(w,i>=400?new Vector2(-5,1):i>=200?new Vector2(-5,5.3f):i>=70?new Vector2(7,5.3f):new Vector2(7,0));Step(w);}Check("actual Won and next visible",w.State.Phase==LevelPhase.Won&&((UnityEngine.UI.Button)new SerializedObject(Object.FindObjectOfType<HUDView>()).FindProperty("nextButton").objectReferenceValue).gameObject.activeInHierarchy);n=w.CompletedStepCount;for(int i=0;i<25;i++)Step(w);Check("Won freezes and no resume",w.CompletedStepCount==n&&!w.Level.TogglePause());w=await Transfer(true);Check("actual next loads unchanged sixth",w.Level.CurrentLevelIndex==5&&w.State.RemainingMarks==3&&w.CompletedStepCount==0&&w.PendingMarkCount==0);var result=new{checks,passed=checks.Count(c=>(bool)c.GetType().GetProperty("pass").GetValue(c)),count=checks.Count};System.IO.File.WriteAllText("D:/Code/Polarity/docs/verification/步骤16-布局与流程.json",JsonConvert.SerializeObject(result));return JsonConvert.SerializeObject(result);}return Run();

